    CONSTRAINT publications_update_type_check CHECK (((update_type)::text = ANY ((ARRAY['addendum'::character varying, 'clarification'::character varying, 'correction'::character varying, 'corrigendum'::character varying, 'erratum'::character varying, 'expression_of_concern'::character varying, 'new_edition'::character varying, 'new_version'::character varying, 'partial_retraction'::character varying, 'removal'::character varying, 'retraction'::character varying, 'withdrawal'::character varying])::text[]))),
